const soundFiles={'African bush elephant':'Bee-Threat-Elicits-Alarm-Call-in-African-Elephants-pone.0010346.s001.ogg','Spotted hyena':'Giggling call of a spotted hyena (Crocuta crocuta) - 1472-6785-10-9-S4.oga','Grévy’s zebra':'Grévys zebra (Sound Effects).ogg'};
const animalGrid=document.getElementById('animalGrid'),animalSearch=document.getElementById('animalSearch');let animalKind='all',playingAudio;
function photoFallback(img,name){img.hidden=true;img.insertAdjacentHTML('afterend',`<div class="animal-photo" role="img" aria-label="Photo unavailable for ${name}"></div>`)}
async function loadPhoto(img){if(img.dataset.loaded)return;img.dataset.loaded='1';try{const r=await fetch(`https://en.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(img.dataset.page)}`),d=await r.json(),src=d.thumbnail?.source;if(!src)throw 0;img.src=src}catch(e){photoFallback(img,img.alt.replace(' photograph',''))}}
function renderWildlife(){const q=animalSearch.value.toLowerCase().trim();const rows=wildlife.filter(a=>(animalKind==='all'||a[2]===animalKind)&&(!q||a.join(' ').toLowerCase().includes(q)));animalGrid.innerHTML=rows.length?rows.map(a=>{const hasSound=!!soundFiles[a[0]];return `<article><img class="animal-photo" data-page="${a[4]}" alt="${a[0]} photograph" loading="lazy"><div class="animal-body"><h2>${a[0]}</h2><p>${a[1]}</p><div class="animal-meta"><span>${a[2]}</span><span>${a[3]}</span></div><div class="animal-actions"><small class="photo-credit">Photo: Wikipedia</small><button class="animal-sound" data-sound="${a[0]}" ${hasSound?'':'disabled'}>${hasSound?'▶ Hear real call':'No recording yet'}</button></div></div></article>`}).join(''):'<div class="animal-empty">No species matches that search.</div>';const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){loadPhoto(e.target);observer.unobserve(e.target)}}),{rootMargin:'250px'});document.querySelectorAll('.animal-photo[data-page]').forEach(x=>observer.observe(x));document.querySelectorAll('.animal-sound:not(:disabled)').forEach(b=>b.addEventListener('click',()=>playSound(b)))}
function playSound(button){if(playingAudio)playingAudio.pause();const file=soundFiles[button.dataset.sound];playingAudio=new Audio(`https://commons.wikimedia.org/wiki/Special:FilePath/${encodeURIComponent(file)}`);button.textContent='Loading…';playingAudio.addEventListener('playing',()=>button.textContent='■ Stop');playingAudio.addEventListener('ended',()=>button.textContent='▶ Hear real call');playingAudio.addEventListener('error',()=>{button.textContent='Recording unavailable';button.disabled=true});playingAudio.play().catch(()=>{button.textContent='Tap again to play'})}
document.querySelectorAll('#wildlifeFilters button').forEach(button=>button.addEventListener('click',()=>{animalKind=button.dataset.kind;document.querySelectorAll('#wildlifeFilters button').forEach(x=>x.classList.toggle('selected',x===button));renderWildlife()}));animalSearch.addEventListener('input',renderWildlife);renderWildlife();
